// PUBLISHER: quien lanza el evento
public class GameManager : MonoBehaviour
{
    // Declaración: delegate + event
    public delegate void OnScoreCambioHandler(int nuevoScore);
    public event OnScoreCambioHandler OnScoreCambio;

    int score = 0;

    public void AgregarPuntos(int pts)
    {
        score += pts;
        // Solo el publisher puede invocar el evento
        OnScoreCambio?.Invoke(score);
    }
}

// SUBSCRIBER: quien escucha el evento
public class ScoreUI : MonoBehaviour
{
    [SerializeField] GameManager gm;

    // Suscribir en OnEnable, desuscribir en OnDisable
    void OnEnable()  => gm.OnScoreCambio += ActualizarTexto;
    void OnDisable() => gm.OnScoreCambio -= ActualizarTexto;

    void ActualizarTexto(int score)
    {
        Debug.Log("Score: " + score);
    }
}

// Datos del evento: hereda de EventArgs
public class EnemyDeathEventArgs : System.EventArgs
{
    public int BountyPoints { get; }
    public Vector3 Position  { get; }

    public EnemyDeathEventArgs(int pts, Vector3 pos)
    {
        BountyPoints = pts;
        Position     = pos;
    }
}

public class Enemy : MonoBehaviour
{
    // Patrón estándar: EventHandler<T> ya declara el delegate por nosotros
    public event System.EventHandler<EnemyDeathEventArgs> OnDeath;

    public void Die()
    {
        var args = new EnemyDeathEventArgs(100, transform.position);
        OnDeath?.Invoke(this, args); // sender = this
    }
}

// Suscriptor
public class AchievementSystem : MonoBehaviour
{
    [SerializeField] Enemy enemy;

    void OnEnable()  => enemy.OnDeath += HandleDeath;
    void OnDisable() => enemy.OnDeath -= HandleDeath;

    void HandleDeath(object sender, EnemyDeathEventArgs e)
    {
        Debug.Log($"Enemigo muerto en {e.Position}, recompensa: {e.BountyPoints}");
    }
}

