public class LevelCompleteArgs : System.EventArgs
{
    public int StarsEarned { get; }
    public float TimeLeft  { get; }

    public LevelCompleteArgs(int stars, float time)
    {
        StarsEarned = stars;
        TimeLeft    = time;
    }
}

public class LevelManager : MonoBehaviour
{
    public event System.EventHandler<LevelCompleteArgs> OnLevelComplete;

    public void CompletarNivel(int estrellas, float tiempoRestante)
    {
        var args = new LevelCompleteArgs(estrellas, tiempoRestante);
        OnLevelComplete?.Invoke(this, args);
    }
}

